func (swq *StablecoinWalletQuery) querySpec() *sqlgraph.QuerySpec {
	_spec := sqlgraph.NewQuerySpec(stablecoinwallet.Table, stablecoinwallet.Columns, sqlgraph.NewFieldSpec(stablecoinwallet.FieldID, field.TypeString))
	_spec.From = swq.sql
	if unique := swq.ctx.Unique; unique != nil {
		_spec.Unique = *unique
	} else if swq.path != nil {
		_spec.Unique = true
	}
	if fields := swq.ctx.Fields; len(fields) > 0 {
		_spec.Node.Columns = make([]string, 0, len(fields))
		_spec.Node.Columns = append(_spec.Node.Columns, stablecoinwallet.FieldID)
		for i := range fields {
			if fields[i] != stablecoinwallet.FieldID {
				_spec.Node.Columns = append(_spec.Node.Columns, fields[i])
			}
		}
		if swq.withCurrency != nil {
			_spec.Node.AddColumnOnce(stablecoinwallet.FieldCoinID)
		}
		if swq.withStablecoinNetworks != nil {
			_spec.Node.AddColumnOnce(stablecoinwallet.FieldNetworkID)
		}
	}
	if ps := swq.predicates; len(ps) > 0 {
		_spec.Predicate = func(selector *sql.Selector) {
			for i := range ps {
				ps[i](selector)
			}
		}
	}
	if limit := swq.ctx.Limit; limit != nil {
		_spec.Limit = *limit
	}
	if offset := swq.ctx.Offset; offset != nil {
		_spec.Offset = *offset
	}
	if ps := swq.order; len(ps) > 0 {
		_spec.Order = func(selector *sql.Selector) {
			for i := range ps {
				ps[i](selector)
			}
		}
	}
	return _spec
}

func (swq *StablecoinWalletQuery) sqlQuery(ctx context.Context) *sql.Selector {
	builder := sql.Dialect(swq.driver.Dialect())
	t1 := builder.Table(stablecoinwallet.Table)
	columns := swq.ctx.Fields
	if len(columns) == 0 {
		columns = stablecoinwallet.Columns
	}
	selector := builder.Select(t1.Columns(columns...)...).From(t1)
	if swq.sql != nil {
		selector = swq.sql
		selector.Select(selector.Columns(columns...)...)
	}
	if swq.ctx.Unique != nil && *swq.ctx.Unique {
		selector.Distinct()
	}
	for _, p := range swq.predicates {
		p(selector)
	}
	for _, p := range swq.order {
		p(selector)
	}
	if offset := swq.ctx.Offset; offset != nil {
		// limit is mandatory for offset clause. We start
		// with default value, and override it below if needed.
		selector.Offset(*offset).Limit(math.MaxInt32)
	}
	if limit := swq.ctx.Limit; limit != nil {
		selector.Limit(*limit)
	}
	return selector
}

